changes.new:
$null=Child $compiler @('--version','--verbose')
foreach($variant in @('native','checked','scalar','scalar-checked')) {
    $auditExe=Join-Path $work "state-audit-$variant.exe"
    $auditArgv=@((Join-Path $PSScriptRoot 'state_audit.rs'),'--edition=2024','-C','panic=abort','-C','opt-level=3','-C','link-arg=/DEBUG:NONE','--cfg','khc_mixture_reuse_audit','--cfg','khc_balanced_kt_audit','-o',$auditExe)
    if($variant.EndsWith('checked')){$auditArgv+=@('-C','overflow-checks=yes')}
    if($variant.StartsWith('scalar')){$auditArgv+=@('--cfg','khc_force_scalar_batch')}
    $null=Child $compiler $auditArgv
    Hold $auditExe "$variant-state-audit"
    $auditText=Child $auditExe @()
    $summary=$auditText|ConvertFrom-Json
    if($summary.status -cne 'node_u32_state_and_bounds_verified_not_timing' -or $summary.transitions -ne 65644 -or $summary.storage_cases -ne 9 -or $summary.storage_rejections -ne 3 -or $summary.state_events -ne 131072 -or $summary.path_values_per_event -ne 85 -or $summary.post_error_events -ne 1 -or $summary.invalid_class_refusals -ne 4){throw 'numeric/state audit coverage'}
    if($summary.old_node_bytes -ne 16 -or $summary.new_node_bytes -ne 12 -or $summary.node_count -ne 917497 -or $summary.logical_node_bytes -ne 11009964 -or $summary.saved_node_bytes -ne 3669988 -or $summary.minimum_alpha -ne 7 -or $summary.maximum_updated_weight -ne 4294967289){throw 'node bounds/layout'}
    $stateSummaries.Add([pscustomobject]@{variant=$variant;summary=$summary;stdout=$auditText})
    $checks.Add("$variant-streamed-node-storage-and-state-e2e")
}
foreach($summary in $stateSummaries){if($summary.stdout -cne $stateSummaries[0].stdout){throw 'four-condition numeric/state output differs'}}
$checks.Add('four-condition-full-numeric-state-summary-identical')
